############ publishes-a-site-directory ############
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { parseWranglerConfig, publishedDir, wranglerConfigPath, WRANGLER_CONFIGS } from '../lib.mjs';

// WHY. The wrangler config is the whole boundary of what reaches a public URL: the
// release uploads `assets.directory` and nothing else, and the repo around it holds
// the vendored mount, the queue's workers and the packs. A widened or missing
// directory is not a broken build — the deploy succeeds and publishes the agent
// tooling, or publishes nothing, and neither looks wrong anywhere.
//
// SCOPE. The one wrangler config the release reads (root or one directory down,
// JSON or JSONC). A repo declaring this pack has said it deploys this way, so a
// missing config is a finding rather than a reason to stay quiet.

const rule = {
  id: 'cloudflare-site/publishes-a-site-directory',
  severity: 'blocking',
  since: '2026-09-13',
  description: 'The wrangler config names a published subdirectory that exists, and pins a compatibility date',
  doc: 'packs/cloudflare-site/RULES.md',
  why: 'assets.directory is the only boundary between the published site and the repo holding the mount, the packs and the queue workers',

  run(ctx) {
    const configPath = wranglerConfigPath(ctx.tracked);
    if (!configPath) {
      return [finding(rule, {
        file: WRANGLER_CONFIGS[0],
        what: 'no wrangler.json or wrangler.jsonc at the repo root or one directory down',
        fix: 'add the wrangler config the release reads — it names the tree to upload (assets.directory) and the custom domains to attach; a TOML config is a wrangler setup this pack does not read',
      })];
    }

    const config = parseWranglerConfig(ctx.read(configPath));
    if (config === null) {
      return [finding(rule, {
        file: configPath,
        what: `${configPath} does not parse as JSON`,
        fix: 'fix the syntax — the release, the version stamp and these checks all read this file, and a config they cannot parse stops the release at the gate',
      })];
    }

    const out = [];
    const dir = publishedDir(config, configPath);
    if (!dir) {
      out.push(finding(rule, {
        file: configPath,
        what: 'the config declares no assets.directory',
        fix: 'set assets.directory to the one tree the site publishes — without it wrangler deploy has no target at all',
      }));
    } else if (dir === '' || dir === '.' || dir === configPath.slice(0, Math.max(0, configPath.lastIndexOf('/')))) {
      out.push(finding(rule, {
        file: configPath,
        what: `assets.directory publishes ${dir === '' || dir === '.' ? 'the repo root' : dir}`,
        fix: 'point assets.directory at a subdirectory holding the site and nothing else — publishing the tree that holds it publishes the vendored mount, the packs and the queue workers to a public URL',
      }));
    } else if (!ctx.tracked.some((f) => f.startsWith(`${dir}/`))) {
      out.push(finding(rule, {
        file: configPath,
        what: `assets.directory names ${dir}, which holds no tracked file`,
        fix: `create ${dir} with the site in it, or point assets.directory at the tree that is actually published — a deploy of an empty directory serves a 404 to every visitor and reports success`,
      }));
    }

    if (!config.compatibility_date) {
      out.push(finding(rule, {
        file: configPath,
        what: 'the config declares no compatibility_date',
        fix: 'pin compatibility_date, so the runtime a release lands on is a value in the repo rather than whatever the deploy day defaults to',
      }));
    }

    return out;
  },
};

export default rule;
############ no-second-publisher ############
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../../engine/checks/helpers/github-workflows.mjs';
import { parseWranglerConfig, publishedDir, wranglerConfigPath } from '../lib.mjs';

// WHY. The release task is the one path to production: it cuts the version, gates on
// what has landed, and parks where a person has to act. A second publisher has none
// of that — a workflow that deploys ships the tree with no version cut and no park
// lane, and a green run looks exactly like success; a `CNAME` file left under the
// published tree is GitHub Pages still claiming the domain the Worker now serves,
// which is the leftover of a previous host rather than a setting anyone chose.
//
// Both are evaluated rather than handed to an adopter as a checklist item: a step
// that reads "turn the old host off, if it is on" is a no-op for most repos, and a
// checklist of no-ops teaches its reader to skim the list that exists to stop them.
//
// SCOPE. The repo's own workflows, and the published tree named by the wrangler
// config. A commented-out step is not a publisher.

// The publishing steps a site repo reaches for: GitHub Pages' three actions, the
// wrangler action, and a bare `wrangler deploy` in a `run:` line.
const PUBLISHES = /actions\/(deploy-pages|upload-pages-artifact|configure-pages)|cloudflare\/wrangler-action|wrangler(@\S+)?\s+(pages\s+)?deploy/;

const rule = {
  id: 'cloudflare-site/no-second-publisher',
  severity: 'blocking',
  since: '2026-09-13',
  description: 'Nothing but the site-release task publishes the site',
  doc: 'packs/cloudflare-site/RULES.md',
  why: 'a second publisher ships the tree with no version cut, no gate and no park lane — and its green run looks exactly like success',

  run(ctx) {
    const out = [];

    for (const file of workflowFiles(ctx)) {
      const text = ctx.read(file);
      if (text === null) continue;
      text.split('\n').forEach((line, i) => {
        if (/^\s*#/.test(line) || !PUBLISHES.test(line)) return;
        out.push(finding(rule, {
          file,
          line: i + 1,
          what: `${file} publishes the site from a workflow`,
          fix: 'publish from the site-release task instead — `wrangler` is a CLI, so the release needs no `uses:` step, and the task is what cuts the version and parks when Cloudflare refuses',
        }));
      });
    }

    const configPath = wranglerConfigPath(ctx.tracked);
    const dir = configPath && publishedDir(parseWranglerConfig(ctx.read(configPath)), configPath);
    if (dir) {
      for (const file of ctx.tracked.filter((f) => f === `${dir}/CNAME`)) {
        out.push(finding(rule, {
          file,
          what: `${file} claims the domain for GitHub Pages`,
          fix: 'delete it — the custom domains are the wrangler config\'s routes, Cloudflare writes the DNS record as the deploy attaches them, and a CNAME file left here keeps the old host claiming the same name',
        }));
      }
    }

    return out;
  },
};

export default rule;
############ version-stamp-matches-package ############
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { parseWranglerConfig, publishedDir, wranglerConfigPath } from '../lib.mjs';

// WHY. A published page names the released version in a `title="version …"`
// attribute, so a visitor can say which build they are looking at. That number is a
// copy of `package.json`'s version — the single source the release bumps — and a
// copy that drifts is worse than no number at all: it names a build that is not the
// one being served, and nothing about the page looks wrong.
//
// The copy is generated, not hand-maintained: `bump-version.mjs` writes the version
// into `package.json` and stamps it into every published page, in the same run. This
// rule is that generator's drift guard — it fires on what a hand-edit, a
