//   data/venues.json
//   data/days/<YYYY-MM-DD>.json + data/days/index.json
//
// So a file under `data/` that isn't one of those shapes came from a hand, a''',
'''// The repo holds two data trees and normalize.py writes both: `site/data/`, the
// wire files the browser fetches, and `data/`, the pipeline's own working files.
// Its module header is the authoritative list:
//
//   site/data/normalized/shows.min.json, availability.min.json, descriptions.min.json
//   site/data/venues.json
//   site/data/days/<YYYY-MM-DD>.json + site/data/days/index.json
//   data/normalized/shows.json                   the master, which no page fetches
//
// Both trees are scanned, because the hazard is the same on either side of the
// publish boundary — worse on the published one, where an unowned file is served
// to visitors. So a file under either that isn't one of those shapes came from a hand, a''')

s = s.replace('''const ALLOWED_PATTERNS = [
  /^data\\/normalized\\/[^/]+\\.json$/,
  /^data\\/days\\/[^/]+\\.json$/,
];''',
'''const ALLOWED_PATTERNS = [
  /^site\\/data\\/normalized\\/[^/]+\\.json$/,
  /^site\\/data\\/days\\/[^/]+\\.json$/,
  /^data\\/normalized\\/[^/]+\\.json$/,
];

// The two roots a committed data file may sit under. Named once so the scan, the
// findings and this file's own prose cannot drift apart.
const DATA_ROOTS = ['site/data/', 'data/'];''')

s = s.replace("const ALLOWED_FILES = new Set(['data/venues.json', 'data/shows.json']);",
              "const ALLOWED_FILES = new Set(['site/data/venues.json', 'data/shows.json']);")
s = s.replace("['data/jerusalem/shows.json', 'scraper/jerusalem/fetch.py'],",
              "['site/data/jerusalem/shows.json', 'scraper/jerusalem/fetch.py'],")
s = s.replace("for (const f of ctx.files.filter((p) => p.startsWith('data/')).sort()) {",
              "for (const f of ctx.files.filter((p) => DATA_ROOTS.some((r) => p.startsWith(r))).sort()) {")
s = s.replace("description: \"Every committed file under data/ is one of scraper/normalize.py's outputs — no hand-made files, no probe dumps, no raw cache\",",
              "description: \"Every committed file under site/data/ or data/ is one of scraper/normalize.py's outputs — no hand-made files, no probe dumps, no raw cache\",")
s = s.replace("'data/ is generator output that the browser fetches and the next refresh-shows run rewrites wholesale,",
              "'both data trees are generator output — site/data/ is fetched by the browser and the next refresh-shows run rewrites them wholesale,")
s = s.replace("`delete ${f} — everything under data/ is scraper/normalize.py's output (data/venues.json, data/normalized/*.json, data/days/*.json), plus",
              "`delete ${f} — everything under site/data/ and data/ is scraper/normalize.py's output (site/data/venues.json, site/data/normalized/*.json, site/data/days/*.json, data/normalized/shows.json), plus")
s = s.replace("what: `${file} is under data/ but is not something a generator in this repo produces`,",
              "what: `${file} is under a data tree but is not something a generator in this repo produces`,")
p.write_text(s)

# ---------- lookup-indices ----------
p = pathlib.Path("lookup-indices.mjs")
s = p.read_text()
for old, new in [
    ("const DAY_FILE = /^data\\/days\\/\\d{4}-\\d{2}-\\d{2}\\.json$/;", "const DAY_FILE = /^site\\/data\\/days\\/\\d{4}-\\d{2}-\\d{2}\\.json$/;"),
    ("const MASTER = 'data/normalized/shows.min.json';", "const MASTER = 'site/data/normalized/shows.min.json';"),
    ("const AVAILABILITY = 'data/normalized/availability.min.json';", "const AVAILABILITY = 'site/data/normalized/availability.min.json';"),
    ("const LOOKUPS = 'data/venues.json';", "const LOOKUPS = 'site/data/venues.json';"),
]:
    assert old in s, old
    s = s.replace(old, new)
p.write_text(s)

# ---------- no-stray-package-json ----------
p = pathlib.Path("no-stray-package-json.mjs")
s = p.read_text()
old = "const ALLOWED = new Set(['package.json', 'plan/package.json']);"
assert old in s
p.write_text(s.replace(old, "const ALLOWED = new Set(['package.json', 'site/plan/package.json']);"))
print("three checks repointed")
